#!/usr/bin/env node
/**
 * Apply generated model featured_attachments to Shopify model metaobjects.
 *
 * Input defaults to outputs/HEAVY_IRON_MODEL_FEATURED_ATTACHMENTS_PLAN.csv
 * generated by scripts/generate-controlled-attachment-fitments.mjs.
 *
 * Dry-run by default. Use --apply to write Shopify.
 */

import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const args = new Set(process.argv.slice(2).filter((arg) => arg.startsWith("--") && !arg.includes("=")));
const argValue = (name, fallback) => {
  const prefix = `${name}=`;
  const found = process.argv.slice(2).find((arg) => arg.startsWith(prefix));
  return found ? found.slice(prefix.length) : fallback;
};

const APPLY = args.has("--apply");
const STORE = argValue("--store", "tracktech-530.myshopify.com");
const INPUT = argValue(
  "--input",
  path.resolve("../../outputs/HEAVY_IRON_MODEL_FEATURED_ATTACHMENTS_PLAN.csv"),
);
const OUT = argValue(
  "--out",
  path.resolve("../../outputs/HEAVY_IRON_FEATURED_ATTACHMENTS_APPLY_RESULTS.csv"),
);

function parseCsvLine(line) {
  const out = [];
  let current = "";
  let quoted = false;
  for (let i = 0; i < line.length; i += 1) {
    const char = line[i];
    if (char === '"' && line[i + 1] === '"') {
      current += '"';
      i += 1;
    } else if (char === '"') {
      quoted = !quoted;
    } else if (char === "," && !quoted) {
      out.push(current);
      current = "";
    } else {
      current += char;
    }
  }
  out.push(current);
  return out;
}

function csvEscape(value) {
  return `"${String(value ?? "").replace(/"/g, '""')}"`;
}

function writeCsv(filePath, rows) {
  if (!rows.length) {
    fs.writeFileSync(filePath, "");
    return;
  }
  const headers = Object.keys(rows[0]);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(
    filePath,
    [headers.join(","), ...rows.map((row) => headers.map((header) => csvEscape(row[header])).join(","))].join("\n"),
  );
}

function readPlan(filePath) {
  const lines = fs.readFileSync(filePath, "utf8").trim().split(/\n/);
  const headers = parseCsvLine(lines.shift());
  const index = Object.fromEntries(headers.map((header, i) => [header, i]));
  return lines.map((line) => {
    const columns = parseCsvLine(line);
    return {
      model_key: columns[index.model_key],
      make: columns[index.make],
      model: columns[index.model],
      shopify_metaobject_gid: columns[index.shopify_metaobject_gid],
      featured_attachment_product_gids: JSON.parse(columns[index.featured_attachment_product_gids] || "[]"),
      featured_attachment_skus: columns[index.featured_attachment_skus],
      categories: columns[index.categories],
      max_score: columns[index.max_score],
      source: columns[index.source],
    };
  });
}

function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

function shopifyGql(query, variables = {}, allowMutations = false) {
  const cmd = ["store", "execute", "--store", STORE, "--query", query, "--json"];
  if (Object.keys(variables).length) cmd.push("--variables", JSON.stringify(variables));
  if (allowMutations) cmd.push("--allow-mutations");
  const stdout = execFileSync("shopify", cmd, {
    encoding: "utf8",
    env: {
      ...process.env,
      SHOPIFY_CLI_AGENT_INFO: "n:codex|v:1|p:openai",
      SHOPIFY_CLI_AGENT_IDS: "s:heavy-iron-theme|r:featured-attachments|i:codex-desktop",
    },
    stdio: ["ignore", "pipe", "pipe"],
  });
  const jsonStart = stdout.indexOf("{");
  return JSON.parse(jsonStart >= 0 ? stdout.slice(jsonStart) : stdout);
}

function applyBatch(rows) {
  const variableDefs = [];
  const mutationFields = [];
  const variables = {};
  rows.forEach((row, index) => {
    variableDefs.push(`$id${index}: ID!`, `$fields${index}: [MetaobjectFieldInput!]!`);
    mutationFields.push(`
      u${index}: metaobjectUpdate(id: $id${index}, metaobject: { fields: $fields${index} }) {
        metaobject { id handle }
        userErrors { field message code }
      }`);
    variables[`id${index}`] = row.shopify_metaobject_gid;
    variables[`fields${index}`] = [
      {
        key: "featured_attachments",
        value: JSON.stringify([...new Set(row.featured_attachment_product_gids)]),
      },
    ];
  });
  const mutation = `mutation UpdateFeaturedAttachments(${variableDefs.join(", ")}) { ${mutationFields.join("\n")} }`;
  return shopifyGql(mutation, variables, true);
}

async function main() {
  const planRows = readPlan(INPUT).filter((row) =>
    row.shopify_metaobject_gid && row.featured_attachment_product_gids.length,
  );
  const results = planRows.map((row) => ({
    model_key: row.model_key,
    make: row.make,
    model: row.model,
    shopify_metaobject_gid: row.shopify_metaobject_gid,
    attachment_count: row.featured_attachment_product_gids.length,
    featured_attachment_skus: row.featured_attachment_skus,
    categories: row.categories,
    action: APPLY ? "update_featured_attachments" : "would_update_featured_attachments",
    result: APPLY ? "queued" : "dry-run",
    error: "",
  }));

  if (APPLY) {
    for (const batch of chunk(results, 20)) {
      const planBatch = batch.map((result) => planRows.find((row) => row.model_key === result.model_key));
      const data = applyBatch(planBatch);
      batch.forEach((result, index) => {
        const payload = data[`u${index}`];
        const errors = payload?.userErrors || [];
        if (errors.length) {
          result.result = "error";
          result.error = JSON.stringify(errors);
        } else {
          result.result = "updated";
        }
      });
    }
  }

  writeCsv(OUT, results);
  const summary = {
    mode: APPLY ? "apply" : "dry-run",
    input: INPUT,
    output: OUT,
    rows: results.length,
    attachment_refs: results.reduce((sum, row) => sum + Number(row.attachment_count || 0), 0),
    results: results.reduce((memo, row) => {
      memo[row.result] = (memo[row.result] || 0) + 1;
      return memo;
    }, {}),
  };
  console.log(JSON.stringify(summary, null, 2));
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
